-- Add immutable recent-callback contracts without changing saved configurations.
ALTER TABLE asterisk.voice_agent_versions DROP CONSTRAINT IF EXISTS voice_agent_contract_check;
ALTER TABLE asterisk.voice_agent_versions ADD CONSTRAINT IF NOT EXISTS voice_agent_contract_check CHECK (workflow_version > 0 AND contract_version IN (1,2,3,4,5,6,7));
INSERT IGNORE INTO asterisk.voice_agent_builtin_tools VALUES ('pbx.transfer',2,CONVERT(X'' USING utf8mb4));
INSERT IGNORE INTO asterisk.voice_agent_builtin_tools VALUES ('pbx.find_recent_callers',1,CONVERT(X'' USING utf8mb4));
CREATE OR REPLACE SQL SECURITY DEFINER VIEW asterisk.voice_agent_runtime_tools AS SELECT tool_id,tool_version,manifest_json FROM asterisk.voice_agent_builtin_tools WHERE (tool_id IN ('directory.find_destinations','telephony.transfer') AND tool_version IN (1,2)) OR (tool_id IN ('pbx.find_destinations','pbx.find_recent_callers') AND tool_version=1) OR (tool_id='pbx.transfer' AND tool_version IN (1,2));
ALTER TABLE asteriskcdrdb.voice_agent_run_events MODIFY COLUMN tool_id ENUM('directory.find_destinations','telephony.transfer','pbx.find_destinations','pbx.transfer','pbx.find_recent_callers') NULL;
INSERT IGNORE INTO asterisk.voice_agent_schema (version) VALUES (13);
